        let retry_after = response2
            .headers()
            .get("x-retry-after")
            .and_then(|v| v.to_str().ok())
            .and_then(|v| v.parse::<i64>().ok());
        assert!(
            retry_after.is_some(),
            "x-retry-after header should be present"
        );
        assert!(retry_after.unwrap() > 0, "retry_after should be positive");
    }

